function cheapestSawing(n: number, cuts: number[]): number {
  const solve = (lo: number, hi: number): number => {
    let best = Infinity;
    for (const c of cuts) {
      if (c > lo && c < hi) best = Math.min(best, solve(lo, c) + solve(c, hi));
    }
    return best === Infinity ? 0 : best + (hi - lo);
  };
  return solve(0, n);
}

