class Solution:
    def cheapestSawing(self, n: int, cuts: List[int]) -> int:
        def solve(lo, hi):
            inside = [c for c in cuts if lo < c < hi]
            if not inside:
                return 0
            return hi - lo + min(solve(lo, c) + solve(c, hi) for c in inside)

        return solve(0, n)

