function cheapestSawing(n: number, cuts: number[]): number {
  const p = [0, ...[...cuts].sort((a, b) => a - b), n];
  const k = p.length;
  const dp = Array.from({ length: k }, () => new Array(k).fill(0));
  for (let gap = 2; gap < k; gap++) {
    for (let i = 0; i + gap < k; i++) {
      const j = i + gap;
      let best = Infinity;
      for (let m = i + 1; m < j; m++) best = Math.min(best, dp[i][m] + dp[m][j]);
      dp[i][j] = best + p[j] - p[i];
    }
  }
  return dp[0][k - 1];
}

