    def cheapestSawing(self, n: int, cuts: List[int]) -> int:
        p = [0] + sorted(cuts) + [n]
        k = len(p)
        dp = [[0] * k for _ in range(k)]
        for gap in range(2, k):
            for i in range(k - gap):
                j = i + gap
                dp[i][j] = p[j] - p[i] + min(dp[i][m] + dp[m][j] for m in range(i + 1, j))
        return dp[0][k - 1]

